#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m, k;
    while (cin >> n >> m >> k) {
        if (k < 1 || k > 2 * n * m) continue;

        long long column = (k - 1) / (2 * m) + 1;
        long long row = ((k - 1) % (2 * m)) / 2 + 1;
        char side = (k & 1) ? 'L' : 'R';

        cout << column << ' ' << row << ' ' << side << '\n';
    }

    return 0;
}

